\label{thm:gp_concentration_inequalities}
    Let $f:X \to \mathbb{R}$, $\operatorname{\mathbb{X}} = \{x_i\}_{i=1}^N$ be a set of $N$ points $x \in X$, $\operatorname{\mathbb{Y}} = \{y_i = f(x_i) + \xi\}_{x_i \in \operatorname{\mathbb{X}}}$ be a set of noisy observations $y_i$ of $f(x_i)$ with $R$ sub-gaussian noise $\xi$, and $k: X \times X \to \mathbb{R}$ be a positive-definite kernel function.  If $f$ has $B$-bounded RKHS norm for some $B > 0$, \textit{i.e.} $\|f\|_{RKHS} \leq B$, then, with $\mu_N$ and $\sigma_N$ as per~\eqref{eq:gp_functions} and with minimum probability $1-\delta$,
    \begin{equation}
        |\mu_N(x) - f(x)| \leq \left(B + R \sqrt{2 \ln{\frac{\sqrt{\det\left((1+\frac{2}{N})I_N + \mathbb{K}_N\right)}}{\delta}}}\right) \sigma_N(x),~\forall~x \in X.
    \end{equation}

\label{def:value-at-risk}
    The \underline{Value-at-Risk} level $\epsilon \in [0,1]$ of a scalar random variable $X$ defined over the probability space $(\Omega,\mathcal{F},\mathbb{P})$ with distribution $\pi$ is defined as the $(1-\epsilon)-th$ quartile of $X$, \textit{i.e.}
    \begin{equation}
        \operatorname{VaR}_{\epsilon}(X) \triangleq c\, \operatorname*{~\mathrm{s.t.}~}\, c = \inf\{z \in \mathbb{R}~|~ \operatorname{\mathbb{P}}_{\pi}[X\leq z] \geq 1-\epsilon\}.
    \end{equation}

\label{def:surface-at-risk}
    The \underline{Surface-at-Risk} level $\epsilon \in [0,1]$ of a scalar stochastic process $S$ indexed by the set $\mathcal{X}$ is the indexed collection of the Values-at-Risk level $\epsilon$ of each random variables $S_x$ comprising $S$:
    \begin{equation}
        \operatorname{SaR}_{\epsilon}(S,x) = \operatorname{VaR}_{\epsilon}(S_x).
    \end{equation}

\label{problem_statement}
    Identify an upper bound to the \textit{Surface-at-Risk} at some risk-level $\epsilon \in [0,1]$ for the disturbance-norm stochastic process $S$ as per Definition~\ref{def:disturbance_stochastic_process} with Surfaces-at-Risk as defined in Definition~\ref{def:surface-at-risk}.  Specifically, identify an estimate $\operatorname{\mathbb{SR}}_{\epsilon}$ such that,
    \begin{equation}
        \label{eq:upper_bounding_surface}
        \operatorname{\mathbb{SR}}_{\epsilon}(S,\hat{x}) \geq \operatorname{SaR}_{\epsilon}(S,\hat{x}),~\forall~\hat x \in \hat{\mathcal{X}}.
    \end{equation}

\label{assump:bounded_discrepancy}
    For the disturbance-norm stochastic process $S$ in Definition~\ref{def:disturbance_stochastic_process}, the \textit{Surface-at-Risk} at a given risk-level $\epsilon \in [0,1]$ has bounded discrepancy. \textit{I.e.} $\exists~\alpha,\beta \in \mathbb{R}_{\geq 0}$ such that,
    \begin{equation}
        \forall~\hat{x}_i, \hat{x}_j \in \hat{\mathcal{X}},~\|\hat{x}_i - \hat{x}_j\| \leq \alpha \implies |\operatorname{SaR}_{\epsilon}(S,\hat{x}_i) - \operatorname{SaR}_{\epsilon}(S,\hat{x}_j)| \leq \beta.
    \end{equation}

\label{prop:group_samples}
    Let $\{X_i\}_{i=1}^N$ be a collection of $N$ scalar random variables with (perhaps) different distributions $\{\pi_i\}_{i=1}^N$, and let $\{x_i\}_{i=1}^N$ be a set of $N$ samples of these random variables, one sample per each random variable, \textit{i.e.} $x_i$ is a sample of $X_i$.  Then, for any $\epsilon \in [0,1]$, the probability that at least one sample $x_{\ell} \in \{x_i\}_{i=1}^N$ is greater than the Value-at-Risk level $\epsilon$ of its corresponding random variable $X_{\ell}$ is equivalent to $1-(1-\epsilon)^N$, \textit{i.e.} with $\operatorname{VaR}$ as per Definition~\ref{def:value-at-risk} and $\forall~\epsilon \in [0,1]$,
    \begin{equation}
        \operatorname{\mathbb{P}}_{\pi_1,\pi_2,\dots,\pi_N}\left[\exists~x_{\ell} \in \{x_i\}_{i=1}^N \operatorname*{~\mathrm{s.t.}~} x_{\ell} \geq \operatorname{VaR}_{\epsilon}(X_{\ell}) \right] \geq 1-(1-\epsilon)^N.
    \end{equation}

\label{thm:main_theorem}
    Let $\alpha,\beta,\operatorname{N_{RV}},\operatorname{s},\mu_{\operatorname{s}},\sigma_{\operatorname{s}},$ and $k$ be as defined in Algorithm~\ref{alg:fitting_surface}, let $B > 0$, let $\operatorname{SaR}$ be the \textit{Surface-at-Risk} measure as per Definition~\ref{def:surface-at-risk} for some risk-level $\epsilon \in [0,1]$, let $S$ be the disturbance-norm stochastic process as per Definition~\ref{def:disturbance_stochastic_process}, and let Assumption~\ref{assump:bounded_discrepancy} hold for each data set $\mathcal{D}_{\operatorname{s}}$ in lines~5-7 of Algorithm~\ref{alg:fitting_surface} with respect to the given parameters $\alpha,\beta$.  If $\|\operatorname{\mathbb{SR}}_{\epsilon}(S)\|_{RKHS} \leq B$, then with minimum probability $\left(1-(1-\epsilon)^{\operatorname{N_{RV}}}\right)^{\operatorname{s}}$ the following holds $\forall~\hat{x} \in \hat{\mathcal{X}}$ and $\forall~\operatorname{s} = 1,2,\dots$:
    \begin{equation}
        |\mu_{\operatorname{s}}(\hat{x}) - \operatorname{\mathbb{SR}}_{\epsilon}(S,\hat{x})| \leq B \sigma_{\operatorname{s}}(\hat{x}), \qquad \mu_{\operatorname{s}}(\hat{x}) + B \sigma_{\operatorname{s}}(\hat{x}) \geq \operatorname{SaR}_{\epsilon}(S,\hat{x}).
    \end{equation}

First, by the assumptions above, we know that for each data set $\mathcal{D}_{\operatorname{s}}$ in lines~5-7 of Algorithm~\ref{alg:fitting_surface}, we have taken one sample $\operatorname{\delta}_j$ of $\operatorname{N_{RV}}$ (potentially) different random variables $S_{\hat{x}_j}$.  By Proposition~\ref{prop:group_samples}, we know that with minimum probability $1-(1-\epsilon)^{\operatorname{N_{RV}}}$, the maximum sample $\operatorname{\delta}^*_j \triangleq \max\{\operatorname{\delta}_{\ell} \in \mathcal{D}\}$ is greater than the Value-at-Risk of its corresponding random variable $\operatorname{VaR}_{\epsilon}(S_{\hat{x}^*_j})$ ($\operatorname{VaR}$ is defined in Definition~\ref{def:value-at-risk}).  Since we assume Assumption~\ref{assump:bounded_discrepancy} holds for each such set of random variables, then we know that with minimum probability $1-(1-\epsilon)^{\operatorname{N_{RV}}}$, the sum $\operatorname{\delta}^*_j + \beta$ is greater than the value-at-risk level $\epsilon$ of any sampled random variable, \textit{i.e.} the sum $\operatorname{\delta}^*_j + \beta$  is a non-noisy estimate of $\operatorname{\mathbb{SR}}_{\epsilon}(S,\hat{x}),~\forall~\hat{x} \in \mathcal{D}_{\operatorname{s}}$.  Hence, repeating this same argument for each data point in $\operatorname{\mathbb{X}},\operatorname{\mathbb{Y}}$  and setting $R=0$, as each sampled point is a non-noisy sample of our upper-bounding surface, we recover the results of Theorem~\ref{thm:gp_concentration_inequalities} with minimum probability $(1-(1-\epsilon)^{\operatorname{N_{RV}}})^{\operatorname{s}}$:
\begin{equation}
    \label{eq:gp_sar_estimate}
    |\mu_{\operatorname{s}}(\hat{x}) - \operatorname{\mathbb{SR}}_{\epsilon}(S,\hat{x})| \leq B \sigma_{\operatorname{s}}(\hat{x}),~\forall~\hat{x} \in \hat{\mathcal{X}}.
\end{equation}


\noindent Our final result holds by unraveling the absolute-value inequality in~\eqref{eq:gp_sar_estimate}, as $\operatorname{\mathbb{SR}}_{\epsilon}(S)$ is an upper-bounding surface for $\operatorname{SaR}_{\epsilon}(S)$.
